/// Аргументы `lob touches`: читает суточные файлы, пишет касания живых
/// уровней с признаками практиков. Режим `H3` — без умолчания, как у
/// `levels`; `--h3-k` — тот же пересчёт пола на лету (таск 18).
#[derive(Debug, Args)]
pub struct TouchesArgs {
    /// Корень записи: суточные файлы `<SYMBOL>-*.binlog`.
    #[arg(long, default_value = "data/bybit")]
    pub root: PathBuf,
    /// Символ, например `SOLUSDT`.
    #[arg(long)]
    pub symbol: String,
    /// Режим `H3`: `--h3-mode floor|percentile|notional|strength|both` с флагами
    /// режима (`--h3-lots`, `--h3-usd`, `--h3-strength-pct`, `--h3-strength-window-bps`;
    /// В-61) — общие для нескольких подкоманд.
    #[command(flatten)]
    pub h3: H3Args,
    /// Множитель относительного порога `floor` (таск 18, В-30/D05):
    /// `h3_lots = floor(k × median_trade_lots)` из `instruments.csv`.
    /// Только `--h3-mode floor`.
    #[arg(long)]
    pub h3_k: Option<f64>,
    /// Прогрев в мс: только режим `percentile`; `floor` не читает.
    #[arg(long, default_value_t = DEFAULT_WARMUP_MS)]
    pub warmup_ms: i64,
    /// Скользящее окно `repeat_count` в мс (нужно трекеру, в касания не пишется).
    #[arg(long, default_value_t = DEFAULT_REPEAT_WINDOW_MS)]
    pub repeat_window_ms: i64,
    /// Куда писать касания (по умолчанию `<root>/touches-<symbol>.csv`).
    #[arg(long)]
    pub out: Option<PathBuf>,
    /// Полоса сигнала **подхода** `D` в bps (F1 этапа F, В-73): рядом с
    /// касаниями пишется `approaches-<symbol>.csv` — моменты, когда цена
    /// другой стороны подошла к живому уровню на `D` bps. Без флага записей
    /// подхода нет вовсе (байты касаний прежние).
    ///
    /// **Список значений** (`--approach-bps 10,20,30,50`, владелец 20.09:
    /// в предрегистрацию идут несколько полос) — один реплей, по трекеру на
    /// полосу: первая пишет привычный `approaches-<symbol>.csv`, каждая
    /// следующая — `approaches-<symbol>-D<d>.csv`. Так нельзя сложить полосы
    /// в один файл: момент взвода у разных `D` разный (цена пересекает
    /// широкую полосу раньше узкой), и запись с `D = 20` не даёт корректного
    /// взвода на 50.
    #[arg(long, value_delimiter = ',')]
    pub approach_bps: Vec<i64>,
    /// Минимальный возраст уровня к моменту взвода подхода, секунды (флор
    /// В-71 — 900 с; без флага пола нет). Только вместе с `--approach-bps`.
    #[arg(long, default_value_t = 0)]
    pub approach_min_age_secs: i64,
    /// Заодно измерить **переезды плотностей** (T42, В-46) и записать пары
    /// «смерть → рождение» в этот CSV. Метка `moved` не ставится: измеряется
    /// распределение, границы назначаются отдельным решением.
    #[arg(long)]
    pub moves: Option<PathBuf>,
    /// Окно поиска рождения для `--moves`, мс. Без умолчания: это параметр
    /// измерения, а не константа кода (В-46), и он печатается в шапке.
    #[arg(long)]
    pub moves_window_ms: Option<i64>,
    /// Шаг гистограммы `dt_ms` для `--moves`, мс (без него гистограмма не
    /// печатается: шаг — параметр, а не назначенное число).
    #[arg(long)]
    pub moves_bin_ms: Option<f64>,
    /// Выгрузить **числа практиков** (T42): квантили p10/p50/p90 размера (лоты
    /// / ×H3 / $), расстояния (bps) и времени жизни — по касаниям и по умершим
    /// уровням, отдельно по исходам и по осям В-44.
    #[arg(long)]
    pub numbers: Option<PathBuf>,
    /// Снять требование маркера сверки `verify-<SYMBOL>.status == ok` (отладочные
    /// данные; К1 аудита 18.09).
    #[arg(long, default_value_t = false)]
    pub allow_unverified: bool,
    /// Переносить возраст живых уровней через смежную полночь (аудит дизайна 22.09 Т3): без
    /// флага трекер стартует с нуля в 00:00 UTC — прежние байты. Только режимы без прогрева
    /// (`notional`/`strength`/`both`/`floor`).
    #[arg(long, default_value_t = false)]
    pub carry_age: bool,
    /// Писать записи только этих суток (`YYYY-MM-DD`): корень может нести и прошлые сутки —
    /// для переноса возраста (`--carry-age`), — но кэш суток остаётся кэшем одних суток.
    #[arg(long)]
    pub emit_day: Option<String>,
    /// Заодно записать **уровни** этого же реплея в этот CSV (T-14, план «один проход» T-05):
    /// трекер касаний уже держит записи уровней (`ReplayKeep::ALL`), второй реплей `lob levels`
    /// не нужен. Писатель общий с `lob levels` (`levels::write_levels_csv`) — при тех же
    /// `--h3-*`/`--warmup-ms`/`--repeat-window-ms` те же байты (полоса подхода смертей не
    /// меняет). Без флага файла нет, касания и подходы — прежние байты. Отказ с `--carry-age`,
    /// `--emit-day` и несколькими полосами `--approach-bps`: там эталона `lob levels` нет.
    #[arg(long)]
    pub levels_out: Option<PathBuf>,
}

/// Итог `lob touches` для печати диспетчером.
#[derive(Debug)]
pub struct TouchesSummary {
    pub days: usize,
    pub touches: usize,
    /// Записей подхода (F1) — ноль, если `--approach-bps` не задан.
    pub approaches: usize,
    pub out: PathBuf,
    /// Файлы записей подхода, если они писались: первый — привычное имя
    /// `approaches-<symbol>.csv`, дальше по полосе на файл (`-D<d>`).
    pub approaches_out: Vec<PathBuf>,
    /// Файл уровней и число строк в нём (`--levels-out`), если писался.
    pub levels_out: Option<(PathBuf, usize)>,
}

/// Ширина строки CSV — один источник арности для заголовка и строки:
/// расхождение не компилируется.
    Ok(n)
}

/// Реплей символа тем же `replay_symbol`, что `levels`/`markout`, и запись
/// касаний в CSV. Порядок строк — порядок выдачи трекера внутри суток.
pub fn run_touches(args: &TouchesArgs) -> anyhow::Result<TouchesSummary> {
    // Вся проверка аргументов и режима — до единого байта реплея (W5а):
    // `plan::resolve` отказывает на плохом `--moves-window-ms` или на
    // `--numbers` с режимом без единого H3 сразу, не после дорогого реплея.
    let plan::ResolvedPlan {
        bands,
        cfg,
        h3_lots,
    } = plan::resolve(args)?;

    // Несколько полос — один реплей и по трекеру на полосу (`ReplayStats` на
    // конфигурацию); касания одинаковы у всех (сигнал подхода их не меняет),
    // поэтому берём раскладку первой полосы, а записи подхода — у каждой своей.
    let mut replays = if bands.len() > 1 {
        let cfgs: Vec<crate::lob::levels::LevelsConfig> = bands
            .iter()
            .map(|&d| crate::lob::levels::LevelsConfig {
                approach_bps: Some(d),
                ..cfg
            })
            .collect();
        let mut stats = super::replay_symbol_over_configs_keep(
            &args.root,
            &args.symbol,
            &cfgs,
            ReplayKeep::ALL.with_carry_age(args.carry_age),
        )?;
        anyhow::ensure!(
            stats.len() == cfgs.len(),
            "реплей вернул {} раскладок на {} конфигураций",
            stats.len(),
            cfgs.len()
        );
        std::mem::take(&mut stats)
    } else {
        super::replay_symbol_over_configs_keep(
            &args.root,
            &args.symbol,
            std::slice::from_ref(&cfg),
            ReplayKeep::ALL.with_carry_age(args.carry_age),
        )?
    };
    // Кэш одних суток из корня с прошлыми сутками (перенос возраста): остальные сутки —
    // только прогрев трекера, в файлы не идут.
    if let Some(d) = &args.emit_day {
        for r in &mut replays {
            r.days.retain(|x| &x.day == d);
        }
    }
    // W5в: `remove(0)` без проверки длины паниковал бы вместо чистого отказа,
    // если бы реплей вернул пустую раскладку (контракт `replay_symbol_over_configs_keep`
    // это не гарантирует явно для одной конфигурации).
    anyhow::ensure!(!replays.is_empty(), "реплей не вернул ни одной раскладки");
    let replay = replays.remove(0);
    let out = args
        .out
        .clone()
        .unwrap_or_else(|| args.root.join(format!("touches-{}.csv", args.symbol)));
    if let Some(parent) = out.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)?;
        }
    }
    let mut w = csv::Writer::from_path(&out)?;
    w.write_record(TOUCHES_COLUMNS)?;
    let mut n = 0usize;
    // Записи подхода (F1) — рядом с касаниями, тем же прогоном: трекеры уже
    // их ведут, отдельного реплея не нужно. Файл на полосу: первая — привычное
    // имя `approaches-<symbol>.csv`, остальные — `approaches-<symbol>-D<d>.csv`.
    let approaches_out: Option<Vec<PathBuf>> = if bands.is_empty() {
        None
    } else {
        Some(
            bands
                .iter()
                .enumerate()
                .map(|(k, d)| {
                    let name = if k == 0 {
                        format!("approaches-{}.csv", args.symbol)
                    } else {
                        format!("approaches-{}-D{}.csv", args.symbol, d)
                    };
                    match out.parent() {
                        Some(p) if !p.as_os_str().is_empty() => p.join(name),
                        _ => PathBuf::from(name),
                    }
                })
                .collect(),
        )
    };
    let mut wa: Vec<csv::Writer<std::fs::File>> = Vec::new();
    if let Some(paths) = &approaches_out {
        for path in paths {
            let mut w = csv::Writer::from_path(path)?;
            w.write_record(APPROACHES_COLUMNS)?;
            wa.push(w);
        }
    }
    let mut n_ap = 0usize;
    // Ряд `σ` — по всей записи символа (В-62): окно раннего касания вторых
    // суток смотрит в первые.
    let (sigma_series, second_mids) = {
        let mut all: Vec<crate::lob::markout::MidSample> = Vec::new();
        for day in &replay.days {
            all.extend(day.mids.iter().copied());
        }
        (
            crate::lob::sigma::SigmaSeries::from_mids(&all),
            crate::lob::excursion::SecondMids::from_mids(&all),
        )
    };
    for (day_i, day) in replay.days.iter().enumerate() {
        for t in &day.touches {
            let row = row::touch_row(day, t, &sigma_series, &second_mids);
            w.write_record(row)?;
            n += 1;
        }
        // Записи подхода этих суток (порядок — порядок трекера, детерминирован):
        // по полосе на файл, у каждой полосы — свой трекер и своя раскладка суток.
        for (band_i, writer) in wa.iter_mut().enumerate() {
            let stats = if band_i == 0 {
                &replay
            } else {
                &replays[band_i - 1]
            };
            let Some(band_day) = stats.days.get(day_i) else {
                continue;
            };
            for a in &band_day.approaches {
                let row = row::approach_row(&band_day.day, a);
                writer.write_record(row)?;
                n_ap += 1;
            }
        }
    }
    w.flush()?;
    for writer in wa.iter_mut() {
        writer.flush()?;
    }
    // Минутный ряд середины — рядом с касаниями (S3: режим пула по минутам).
    write_mids1m(&mids1m_path(&out, &args.symbol), &replay.days)?;

    // Уровни того же реплея (T-14): отказы без эталона `lob levels` — в `plan::resolve`.
    let levels_out = match &args.levels_out {
        Some(path) => {
            let n = super::levels::write_levels_csv(path, &replay.days, cfg.repeat_window_ms)?;
            Some((path.clone(), n))
        }
        None => None,
    };

    // Переезды плотностей (T42, В-46) — отдельным файлом: окно поиска
    // проверено `plan::resolve` (W5а), здесь оно уже гарантированно задано и
    // положительно.
    if let Some(path) = &args.moves {
        let window_ms = args
            .moves_window_ms
            .expect("plan::resolve проверил --moves-window-ms");
        moves::run_moves(
            &replay.days,
            window_ms,
            args.moves_bin_ms,
            &args.symbol,
            path,
        )?;
    }

    if args.numbers.is_some() {
        let h3_lots = h3_lots.expect("plan::resolve проверил h3_lots для --numbers");
        numbers::write_numbers(args, &replay, h3_lots, replay.tick_e9, replay.step_e9)?;
    }

    Ok(TouchesSummary {
        days: replay.days.len(),
        touches: n,
        approaches: n_ap,
        out,
        approaches_out: approaches_out.unwrap_or_default(),
        levels_out,
    })
}

#[cfg(test)]
mod tests;
//! Разметка уровней стакана (шаг 1.1 плана).
//!
//! Чистая логика без ввода-вывода: трекер получает наблюдения
//! целочисленных уровней (тики и лоты, `ARCHITECTURE.md` A1) и отдаёт готовые
//! записи с шестью признаками истории. Источник наблюдений — любой, кто умеет
//! отдавать тики и лоты: наша книга через `Book::levels` на реплее, модели
//! очереди крейта в бэктесте и живой торговле (A7 — одна логика на все режимы).

pub mod backtest;
pub mod capacity;
pub mod cells;
pub mod costs;
pub mod excursion;
pub mod final_metrics;
pub mod levels;
pub mod markout;
pub mod markup;
pub mod moves;
pub mod runs;
pub mod shortlist;
pub mod sigma;
pub mod strategy;
pub mod touch_axes;
pub mod watch;

    /// на этом тике, и добавляет объём — иначе молча пропускает. Блочные,
    /// нулевые и поданные раньше рождения не считаются. RPI-сделки идут в
    /// свой счётчик: они исполнились об невидимую заявку, а не об этот уровень
    /// (В-55), поэтому метку исхода не сдвигают. Поиск в карте кучу не
    /// трогает, внутри — одно целое сложение с насыщением.
    pub fn observe_trade(&mut self, tr: TradeHit) {
        if tr.block || tr.lots <= 0 {
            return;
        }
        // Оборот инструмента (сила «×поток»): все неблочные сделки, включая
        // RPI, — это то, что рынок реально проторговал.
        {
            let minute = tr.exch_ms.div_euclid(60_000);
            let slot = minute.rem_euclid(FLOW_WINDOW_MIN as i64) as usize;
            if self.flow_slot_min[slot] != minute {
                self.flow_slot_min[slot] = minute;
                self.flow_ring[slot] = 0;
            }
            self.flow_ring[slot] = self.flow_ring[slot].saturating_add(tr.lots);
        }
        let key = (u8::from(tr.aggressor_is_buy), tr.tick);
        if let Some(lv) = self.live.get_mut(&key) {
            if tr.exch_ms < lv.birth_ms {
                return;
            }
            if tr.rpi {
                lv.rpi = lv.rpi.saturating_add(tr.lots);
            } else {
                lv.traded = lv.traded.saturating_add(tr.lots);
                // Окно реакции (E4): объём в первые секунды идущего касания —
                // по метке исполнения относительно старта касания.
                if let Some(t) = &mut lv.touch {
                    let since_ms = tr.exch_ms.saturating_sub(t.start_ms);
                    for (k, w) in REACTION_WINDOWS_S.iter().enumerate() {
                        if since_ms >= 0 && since_ms < w.saturating_mul(1_000) {
                            t.traded_first_s[k] = t.traded_first_s[k].saturating_add(tr.lots);
                        }
                    }
                }
            }
        }
    pub tick: i64,
    /// Размер сделки в лотах.
    pub lots: i64,
    /// `true` — агрессор-покупатель (ест аск), `false` — продавец (ест бид).
    pub aggressor_is_buy: bool,
    /// Блочная сделка: видимую ликвидность не потребляет, в объём не идёт.
    pub block: bool,
    /// Сделка об RPI-заявку: исполнена об **невидимую** ликвидность
    /// маркет-мейкера, поэтому видимый уровень не потребляет — как и блочная,
    /// но в отличие от неё видна в ленте с 2026-09-15 (бит 1 `attrs`, В-53).
    /// Идёт в отдельный счётчик, а не в `traded_lots`.
    pub rpi: bool,
    /// Время исполнения на матчинге. Сравнимо с меткой кадра; подачи
    /// раньше рождения уровня не считаются.
    pub exch_ms: i64,
}

/// Запись умершего уровня: ключи, шесть признаков истории и место под 1.2.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelRecord {
    /// Сторона книги (нужна шагу 2.1 для полярности по стороне).
/// `LevelTracker` на каждую конфигурацию развешивает уровни и трейды
/// независимо, кормится одними и теми же кадрами (`feed_frames_multi`).
/// Разрыв последовательности (`Err` из `apply`) останавливает файл для всех
/// конфигураций разом, как в `verify`: дальше этот файл недоверен,
/// следующий идёт с чистого листа. Возвращает `ReplayStats` в том же
/// порядке, что `cfgs`.
pub(crate) fn replay_symbol_over_configs(
    root: &Path,
    symbol: &str,
    cfgs: &[LevelsConfig],
) -> anyhow::Result<Vec<ReplayStats>> {
    replay_symbol_over_configs_keep(root, symbol, cfgs, ReplayKeep::ALL)
}

/// То же, но с выбором, что хранить (`ReplayKeep`); `replay_symbol_over_configs`
/// — частный случай `ALL`.
pub(crate) fn replay_symbol_over_configs_keep(
    root: &Path,
    symbol: &str,
    cfgs: &[LevelsConfig],
    keep: ReplayKeep,
) -> anyhow::Result<Vec<ReplayStats>> {
    anyhow::ensure!(
        !cfgs.is_empty(),
        "replay_symbol_over_configs: пустая сетка конфигураций"
    );
    let prefix = format!("{symbol}-");
    let files = list_symbol_binlogs(root, symbol)?;
    if files.is_empty() {
        // Таск 19, критерий 4: каталог старого формата (до таска 19 `lob
        // session` писала `<SYMBOL>.binlog` без даты) не должен молча
        // выглядеть как «нет суточных файлов» — владелец переименовывает
        // руками, но узнать об этом обязан из сообщения, не из тишины.
        // Архивный суффикс (T46) проверяется так же, как обычный.
        for suffix in [
            crate::binlog::BINLOG_SUFFIX,
            crate::binlog::BINLOG_ARCHIVE_SUFFIX,
        ] {
            let name = format!("{symbol}{suffix}");
            let undated = root.join(&name);
            if undated.is_file() {
                anyhow::bail!(
                    "файл `{name}` без даты — запись старого формата, переименуйте в \
                     `{symbol}-<дата>{suffix}` ({} в {})",
                    undated.display(),
                    root.display()
                );
            }
        }
        anyhow::bail!("нет суточных файлов {prefix}*.binlog в {}", root.display());
    }
    // Счётчики GC (байт/записей) — по одному экземпляру на конфигурацию,
    // хотя декодирование общее: значения совпадут у всех, но `+=` читает
    // поле, а не только пишет его (та же идиома, что у `replay_symbol` до
    // этого таска — единственная актуальная альтернатива читать поле
    // разом после цикла тем же способом, каким это уже делает `ReplayStats
    // .days` ниже).
    let mut out: Vec<ReplayStats> = cfgs
        .iter()
        .map(|_| ReplayStats {
            days: Vec::new(),
            bytes: 0,
            records: 0,
            tick_e9: 0,
            step_e9: 0,
            open: Vec::new(),
        })
        .collect();
    let mut work: Vec<DayWork> = Vec::new();
    // Р9 (T-17): кадр стороны — один буфер на весь реплей, а не новый `Vec` на
    // каждую сторону каждого обновления (правило «без аллокаций на событие»).
    let mut obs_buf: Vec<LevelObs> = Vec::with_capacity(256);
    for path in &files {
        let name = path
